package com.enterprise.procurement.model;

import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.ArrayList; import java.util.List;

public class PurchaseApplication {
    private Long id; private String applicationNo; private Long applicantId; private String applicantName; private String department; private String reason; private BigDecimal totalAmount=BigDecimal.ZERO; private Enums.ApplicationStatus status=Enums.ApplicationStatus.DRAFT; private LocalDateTime createdAt; private LocalDateTime updatedAt; private List<Item> items=new ArrayList<>(); private List<ApprovalRecord> approvals=new ArrayList<>();
    public PurchaseApplication(){createdAt=LocalDateTime.now();updatedAt=createdAt;}
    public static class Item { private Long productId; private String productName; private Integer quantity; private BigDecimal unitPrice; public Item(){} public Item(Long p,String n,Integer q,BigDecimal u){productId=p;productName=n;quantity=q;unitPrice=u;} public Long getProductId(){return productId;} public void setProductId(Long v){productId=v;} public String getProductName(){return productName;} public void setProductName(String v){productName=v;} public Integer getQuantity(){return quantity;} public void setQuantity(Integer v){quantity=v;} public BigDecimal getUnitPrice(){return unitPrice;} public void setUnitPrice(BigDecimal v){unitPrice=v;} public BigDecimal amount(){return unitPrice.multiply(BigDecimal.valueOf(quantity));} }
    public static class ApprovalRecord { private Long approverId; private String approverName; private Enums.ApprovalAction action; private String comment; private LocalDateTime actionAt=LocalDateTime.now(); public ApprovalRecord(){} public ApprovalRecord(Long i,String n,Enums.ApprovalAction a,String c){approverId=i;approverName=n;action=a;comment=c;} public Long getApproverId(){return approverId;} public void setApproverId(Long v){approverId=v;} public String getApproverName(){return approverName;} public void setApproverName(String v){approverName=v;} public Enums.ApprovalAction getAction(){return action;} public void setAction(Enums.ApprovalAction v){action=v;} public String getComment(){return comment;} public void setComment(String v){comment=v;} public LocalDateTime getActionAt(){return actionAt;} public void setActionAt(LocalDateTime v){actionAt=v;} }
    public Long getId(){return id;} public void setId(Long v){id=v;} public String getApplicationNo(){return applicationNo;} public void setApplicationNo(String v){applicationNo=v;} public Long getApplicantId(){return applicantId;} public void setApplicantId(Long v){applicantId=v;} public String getApplicantName(){return applicantName;} public void setApplicantName(String v){applicantName=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public BigDecimal getTotalAmount(){return totalAmount;} public void setTotalAmount(BigDecimal v){totalAmount=v;} public Enums.ApplicationStatus getStatus(){return status;} public void setStatus(Enums.ApplicationStatus v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} public LocalDateTime getUpdatedAt(){return updatedAt;} public void setUpdatedAt(LocalDateTime v){updatedAt=v;} public List<Item> getItems(){return items;} public void setItems(List<Item> v){items=v;} public List<ApprovalRecord> getApprovals(){return approvals;} public void setApprovals(List<ApprovalRecord> v){approvals=v;}
}
